import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { primitives } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  // Root container
  const root = new Group();

  // ---- Textured Plane (sprite) ----
  const atlas = config.atlasRegion || { width: 512, height: 320 };
  const aspect = atlas.width / atlas.height;
  const planeGeom = new PlaneGeometry(aspect, 1);
  const planeMat = new MeshBasicNodeMaterial({ transparent: true });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture asynchronously, but return immediately
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then((tex) => {
    planeMat.map = tex;
    planeMat.needsUpdate = true;
    // If atlas region is not full texture, set offset/repeat
    if (atlas.x !== 0 || atlas.y !== 0 || atlas.width !== tex.image.width || atlas.height !== tex.image.height) {
      const u0 = atlas.x / tex.image.width;
      const v0 = atlas.y / tex.image.height;
      const uScale = atlas.width / tex.image.width;
      const vScale = atlas.height / tex.image.height;
      tex.offset.set(u0, v0);
      tex.repeat.set(uScale, vScale);
      tex.needsUpdate = true;
    }
  });

  // ---- Text Content ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // ---- Event Handlers (none for this static node) ----
  root.userData.handlers = {};

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    // Dispose geometry & material
    planeGeom.dispose();
    planeMat.dispose();
    // Texture will be disposed by the loader cache; if we kept a reference we could dispose it here
    // Dispose any text objects
    for (const child of root.children) {
      if (child.isObject3D && child !== planeMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    }
    // No GSAP timelines in this node, but ensure any future ones are killed
    gsap.globalTimeline.clear();
  };

  return root;
}
